INSERT INTO warscape_enemy_family VALUES (45,'icefiends','Icefiends','Small frost elemental 5561.');
INSERT INTO warscape_enemy_family VALUES (46,'pyrefiends','Pyrefiends','Imp 4449 for Pyrefiends, Fire Elemental 1405 for Pyrelords.');
INSERT INTO warscape_enemy_family VALUES (47,'kalphites','Kalphites','Silithid scarab display 7470 for non-poisonous Worker.');
INSERT INTO warscape_enemy_family VALUES (48,'molanisks','Molanisks','Dark carrion grub 7898 stand-in; pre-activated prototype.');
INSERT INTO warscape_enemy_family VALUES (49,'vampyres','Vampyres','Icecrown Darkfallen 31025/31026, spider display 955 for spider form.');
INSERT INTO warscape_enemy_family VALUES (50,'dragons','Dragons','Native green/blue/red/black Whelplings for baby dragons without dragonfire.');
